import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';
class AppShell extends StatelessWidget{final Widget child;const AppShell({required this.child,super.key});@override Widget build(c){final path=GoRouterState.of(c).uri.path;int i=path.startsWith('/plan')?1:path.startsWith('/shopping')?2:path.startsWith('/more')?3:0;return Scaffold(body:SafeArea(child:child),bottomNavigationBar:NavigationBar(selectedIndex:i,onDestinationSelected:(n)=>c.go(['/app','/plan','/shopping','/more'][n]),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.calendar_month_outlined),selectedIcon:Icon(Icons.calendar_month),label:'Plan'),NavigationDestination(icon:Icon(Icons.shopping_cart_outlined),selectedIcon:Icon(Icons.shopping_cart),label:'Einkauf'),NavigationDestination(icon:Icon(Icons.more_horiz),label:'Mehr')])) ;}}
